def perform_float_operation():
    """Perform basic float operations based on user input."""

    # Get user input
    while True:
        user_input = input("Enter a mathematical expression with float operands (e.g., 2.5 + 3.7): ")

        # Check if the input is a valid mathematical expression
        try:
            result = eval(user_input)
            break
        except ValueError:
            print("Invalid input. Please enter a valid mathematical expression.")

    # Perform the operation and print the result
    operation = user_input.split()[0]
    if operation == "+":
        print(f"{float(user_input.split()[1])} + {float(user_input.split()[-1])} = {result}")
    elif operation == "-":
        print(f"{float(user_input.split()[1])} - {float(user_input.split()[-1])} = {result}")
    elif operation == "*":
        print(f"{float(user_input.split()[1])} * {float(user_input.split()[-1])} = {result}")
    elif operation == "/":
        print(f"{float(user_input.split()[1])} / {float(user_input.split()[-1])} = {result}")
    else:
        print("Invalid operation. Please enter a valid mathematical expression.")


# Call the function
perform_float_operation()
```

This program prompts the user to enter a mathematical expression with float operands, validates the input, and performs the corresponding operation before printing the result.
